/** @param {NS} ns */
export async function main(ns) {
  const log = (msg) => ns.print(`[${new Date().toLocaleTimeString()}] ${msg}`);

  try {
    // BFS to find all servers
    const queue = ['home'];
    const visited = new Set(['home']);
    const servers = [];

    while (queue.length > 0) {
      const host = queue.shift();
      servers.push(host);
      try {
        const neighbors = ns.scan(host);
        for (const neighbor of neighbors) {
          if (!visited.has(neighbor)) {
            visited.add(neighbor);
            queue.push(neighbor);
          }
        }
      } catch (e) {}
    }

    log(`Found ${servers.length} servers`);

    // Port opener functions - try each if available
    const openPorts = (host) => {
      let count = 0;
      try { ns.brutessh(host); count++; } catch (e) {}
      try { ns.ftpcrack(host); count++; } catch (e) {}
      try { ns.relaysmtp(host); count++; } catch (e) {}
      try { ns.httpworm(host); count++; } catch (e) {}
      try { ns.sqlinject(host); count++; } catch (e) {}
      return count;
    };

    // Gain root access on servers
    const rooted = [];
    for (const host of servers) {
      if (host === 'home') continue;
      try {
        const hasRoot = ns.hasRootAccess(host);
        if (hasRoot) {
          rooted.push(host);
          continue;
        }
        const reqPorts = ns.getServerNumPortsRequired(host);
        const opened = openPorts(host);
        if (opened >= reqPorts) {
          ns.nuke(host);
          rooted.push(host);
          log(`Rooted: ${host}`);
        }
      } catch (e) {}
    }

    // Filter hackable servers (have money and meet level requirement)
    const targets = rooted.filter(host => {
      try {
        const max = ns.getServerMaxMoney(host);
        const req = ns.getServerRequiredHackingLevel(host);
        return max > 0 && req <= ns.getHackingLevel();
      } catch (e) { return false; }
    });

    if (targets.length === 0) {
      log('No hackable targets found');
      return;
    }

    log(`${targets.length} hackable targets available`);

    // Main loop: find best target and exploit
    while (true) {
      // Pick target with highest max money
      let best = null;
      let bestValue = -1;
      for (const host of targets) {
        try {
          const max = ns.getServerMaxMoney(host);
          if (max > bestValue) {
            best = host;
            bestValue = max;
          }
        } catch (e) {}
      }

      if (!best) {
        await ns.sleep(1000);
        continue;
      }

      try {
        const sec = ns.getServerSecurityLevel(best);
        const minSec = ns.getServerMinSecurityLevel(best);
        const money = ns.getServerMoneyAvailable(best);
        const maxMoney = ns.getServerMaxMoney(best);

        if (sec > minSec + 5) {
          log(`Weakening ${best} (sec: ${sec.toFixed(1)})`);
          await ns.weaken(best);
        } else if (money < maxMoney * 0.75) {
          log(`Growing ${best} (money: ${(money/1e9).toFixed(2)}B)`);
          await ns.grow(best);
        } else {
          log(`Hacking ${best} (money: ${(money/1e9).toFixed(2)}B)`);
          await ns.hack(best);
        }
      } catch (e) {
        log(`Error on ${best}: ${e.message}`);
        await ns.sleep(1000);
      }
    }
  } catch (e) {
    ns.print(`Fatal error: ${e.message}`);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const q = ['home'];
  const visited = new Set(['home']);
  const hosts = [];

  while (q.length > 0) {
    const host = q.shift();
    if (host !== 'home') hosts.push(host);
    const neighbors = ns.scan(host);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        q.push(neighbor);
      }
    }
  }

  const targets = [];
  const myLevel = ns.getHackingLevel();

  for (const host of hosts) {
    if (!ns.hasRootAccess(host)) {
      try { ns.brutessh(host); } catch (e) {}
      if (ns.getServerNumPortsRequired(host) <= 1) {
        try { ns.nuke(host); } catch (e) {}
      }
    }
    if (ns.hasRootAccess(host)) {
      const maxMoney = ns.getServerMaxMoney(host);
      const reqLevel = ns.getServerRequiredHackingLevel(host);
      if (maxMoney > 0 && reqLevel <= myLevel) {
        targets.push({host, maxMoney});
      }
    }
  }

  if (targets.length === 0) {
    ns.print('No targets found');
    return;
  }

  targets.sort((a, b) => b.maxMoney - a.maxMoney);
  const target = targets[0].host;
  const minSec = ns.getServerMinSecurityLevel(target);
  const maxMoney = ns.getServerMaxMoney(target);

  ns.print(`Target: ${target}`);

  while (true) {
    const sec = ns.getServerSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);

    if (sec > minSec + 3) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

